begin;
-- Canonical provider-agnostic creator economy ledger.
create table if not exists public.monetization_accounts (user_id uuid primary key references public.profiles(id) on delete cascade,currency text not null default 'USD' check (currency ~ '^[A-Z]{3}$'),available_cents bigint not null default 0 check (available_cents >= 0),pending_cents bigint not null default 0 check (pending_cents >= 0),lifetime_earned_cents bigint not null default 0 check (lifetime_earned_cents >= 0),lifetime_paid_cents bigint not null default 0 check (lifetime_paid_cents >= 0),updated_at timestamptz not null default now());
create table if not exists public.monetization_ledger (id uuid primary key default gen_random_uuid(),account_user_id uuid not null references public.profiles(id) on delete cascade,counterparty_user_id uuid references public.profiles(id) on delete set null,entry_type text not null check (entry_type in ('tip','subscription','super_follow','paid_content','ad_revenue','sponsorship','digital_product','live_event','live_gift','community','affiliate','topup','platform_fee','creator_earning','refund','chargeback','payout','adjustment')),direction text not null check (direction in ('credit','debit')),amount_cents bigint not null check (amount_cents > 0),currency text not null default 'USD' check (currency ~ '^[A-Z]{3}$'),state text not null default 'pending' check (state in ('pending','available','settled','reversed','voided')),gross_cents bigint not null default 0 check (gross_cents >= 0),platform_fee_cents bigint not null default 0 check (platform_fee_cents >= 0),creator_share_bps integer check (creator_share_bps between 0 and 10000),provider text,provider_event_id text,provider_reference text,idempotency_key text,source_type text,source_id text,description text not null default '',metadata jsonb not null default '{}'::jsonb,reverses_entry_id uuid references public.monetization_ledger(id) on delete restrict,created_at timestamptz not null default now(),available_at timestamptz,settled_at timestamptz);
create unique index if not exists monetization_ledger_idempotency_idx on public.monetization_ledger(account_user_id,idempotency_key) where idempotency_key is not null;
create unique index if not exists monetization_ledger_provider_event_idx on public.monetization_ledger(provider,provider_event_id) where provider is not null and provider_event_id is not null;
create index if not exists monetization_ledger_account_idx on public.monetization_ledger(account_user_id,created_at desc);
create index if not exists monetization_ledger_state_idx on public.monetization_ledger(state,available_at);
create table if not exists public.monetization_payouts (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,amount_cents bigint not null check (amount_cents > 0),currency text not null default 'USD' check (currency ~ '^[A-Z]{3}$'),provider text,provider_payout_id text,destination jsonb not null default '{}'::jsonb,status text not null default 'requested' check (status in ('requested','processing','paid','failed','cancelled')),failure_reason text,idempotency_key text,requested_at timestamptz not null default now(),processed_at timestamptz);
create unique index if not exists monetization_payout_provider_idx on public.monetization_payouts(provider,provider_payout_id) where provider is not null and provider_payout_id is not null;
create unique index if not exists monetization_payout_idempotency_idx on public.monetization_payouts(user_id,idempotency_key) where idempotency_key is not null;
create table if not exists public.monetization_settings (id boolean primary key default true check (id),platform_fee_bps integer not null default 1000 check (platform_fee_bps between 0 and 10000),creator_share_bps integer not null default 9000 check (creator_share_bps between 0 and 10000),minimum_payout_cents bigint not null default 1000 check (minimum_payout_cents >= 0),payout_hold_days integer not null default 7 check (payout_hold_days between 0 and 365),tips_enabled boolean not null default true,subscriptions_enabled boolean not null default true,paid_content_enabled boolean not null default true,ads_enabled boolean not null default true,sponsorships_enabled boolean not null default true,digital_products_enabled boolean not null default true,live_monetization_enabled boolean not null default true,affiliate_enabled boolean not null default true,updated_at timestamptz not null default now());
insert into public.monetization_settings(id) values(true) on conflict(id) do nothing;
alter table public.monetization_accounts enable row level security;
alter table public.monetization_ledger enable row level security;
alter table public.monetization_payouts enable row level security;
alter table public.monetization_settings enable row level security;
create policy monetization_accounts_read_own on public.monetization_accounts for select to authenticated using ((select auth.uid()) = user_id);
create policy monetization_ledger_read_own on public.monetization_ledger for select to authenticated using ((select auth.uid()) = account_user_id or (select auth.uid()) = counterparty_user_id);
create policy monetization_payouts_read_own on public.monetization_payouts for select to authenticated using ((select auth.uid()) = user_id);
create or replace function public.ensure_monetization_account(p_user_id uuid) returns public.monetization_accounts language plpgsql security definer set search_path='' as $$ declare a public.monetization_accounts; begin if (select auth.uid()) is null or (select auth.uid()) <> p_user_id then raise exception 'forbidden'; end if; insert into public.monetization_accounts(user_id) values(p_user_id) on conflict(user_id) do nothing; select * into a from public.monetization_accounts where user_id=p_user_id; return a; end; $$;
revoke all on function public.ensure_monetization_account(uuid) from public; grant execute on function public.ensure_monetization_account(uuid) to authenticated;
create or replace function public.record_creator_earning(p_creator_id uuid,p_entry_type text,p_gross_cents bigint,p_idempotency_key text,p_provider text default null,p_provider_event_id text default null,p_source_type text default null,p_source_id text default null,p_description text default '',p_metadata jsonb default '{}'::jsonb,p_creator_share_bps integer default null) returns public.monetization_ledger language plpgsql security definer set search_path='' as $$ declare s public.monetization_settings; e public.monetization_ledger; share_bps integer; creator_cents bigint; fee_cents bigint; begin if (select auth.uid()) is null then raise exception 'unauthorized'; end if; if (select current_user) <> 'service_role' then raise exception 'server_only'; end if; if p_creator_id is null or p_gross_cents <= 0 then raise exception 'invalid earning'; end if; if p_entry_type not in ('tip','subscription','super_follow','paid_content','ad_revenue','sponsorship','digital_product','live_event','live_gift','community','affiliate','creator_earning') then raise exception 'invalid earning type'; end if; select * into s from public.monetization_settings where id=true; share_bps:=coalesce(p_creator_share_bps,s.creator_share_bps); if share_bps < 0 or share_bps > 10000 then raise exception 'invalid creator share'; end if; creator_cents:=floor((p_gross_cents*share_bps)::numeric/10000); fee_cents:=p_gross_cents-creator_cents; select * into e from public.monetization_ledger where account_user_id=p_creator_id and idempotency_key=p_idempotency_key; if found then return e; end if; insert into public.monetization_accounts(user_id,currency) values(p_creator_id,'USD') on conflict(user_id) do nothing; insert into public.monetization_ledger(account_user_id,entry_type,direction,amount_cents,currency,state,gross_cents,platform_fee_cents,creator_share_bps,provider,provider_event_id,idempotency_key,source_type,source_id,description,metadata,available_at) values(p_creator_id,p_entry_type,'credit',creator_cents,'USD','pending',p_gross_cents,fee_cents,share_bps,p_provider,p_provider_event_id,p_idempotency_key,p_source_type,p_source_id,p_description,coalesce(p_metadata,'{}'::jsonb),now()+make_interval(days=>s.payout_hold_days)) returning * into e; update public.monetization_accounts set pending_cents=pending_cents+creator_cents,lifetime_earned_cents=lifetime_earned_cents+creator_cents,updated_at=now() where user_id=p_creator_id; return e; end; $$;
revoke all on function public.record_creator_earning(uuid,text,bigint,text,text,text,text,text,text,jsonb,integer) from public; grant execute on function public.record_creator_earning(uuid,text,bigint,text,text,text,text,text,text,jsonb,integer) to service_role;
create or replace function public.request_monetization_payout(p_amount_cents bigint,p_provider text,p_destination jsonb default '{}'::jsonb,p_idempotency_key text default null) returns public.monetization_payouts language plpgsql security definer set search_path='' as $$ declare a public.monetization_accounts; s public.monetization_settings; p public.monetization_payouts; begin if (select auth.uid()) is null then raise exception 'unauthorized'; end if; if p_amount_cents<=0 then raise exception 'invalid payout amount'; end if; if p_idempotency_key is not null then select * into p from public.monetization_payouts where user_id=(select auth.uid()) and idempotency_key=p_idempotency_key; if found then return p; end if; end if; select * into s from public.monetization_settings where id=true; select * into a from public.monetization_accounts where user_id=(select auth.uid()) for update; if not found then raise exception 'monetization account not found'; end if; if p_amount_cents<s.minimum_payout_cents then raise exception 'minimum payout is % cents',s.minimum_payout_cents; end if; if p_amount_cents>a.available_cents then raise exception 'insufficient available balance'; end if; insert into public.monetization_payouts(user_id,amount_cents,currency,provider,destination,idempotency_key) values((select auth.uid()),p_amount_cents,a.currency,p_provider,coalesce(p_destination,'{}'::jsonb),p_idempotency_key) returning * into p; insert into public.monetization_ledger(account_user_id,entry_type,direction,amount_cents,currency,state,source_type,source_id,description,metadata,settled_at) values((select auth.uid()),'payout','debit',p_amount_cents,a.currency,'settled','payout',p.id::text,'Creator payout reservation',jsonb_build_object('provider',p_provider),now()); update public.monetization_accounts set available_cents=available_cents-p_amount_cents,lifetime_paid_cents=lifetime_paid_cents+p_amount_cents,updated_at=now() where user_id=(select auth.uid()); return p; end; $$;
revoke all on function public.request_monetization_payout(bigint,text,jsonb,text) from public; grant execute on function public.request_monetization_payout(bigint,text,jsonb,text) to authenticated;
create or replace function public.release_monetization_pending(p_limit integer default 500) returns integer language plpgsql security definer set search_path='' as $$ declare released integer:=0; e record; begin if (select current_user)<>'service_role' then raise exception 'server_only'; end if; for e in select * from public.monetization_ledger where state='pending' and available_at is not null and available_at<=now() order by available_at asc limit greatest(least(p_limit,5000),1) for update skip locked loop update public.monetization_ledger set state='available',settled_at=now() where id=e.id; update public.monetization_accounts set pending_cents=greatest(pending_cents-e.amount_cents,0),available_cents=available_cents+e.amount_cents,updated_at=now() where user_id=e.account_user_id; released:=released+1; end loop; return released; end; $$;
revoke all on function public.release_monetization_pending(integer) from public; grant execute on function public.release_monetization_pending(integer) to service_role;
create or replace view public.creator_monetization_summary with (security_invoker=true) as select a.user_id,a.currency,a.available_cents,a.pending_cents,a.lifetime_earned_cents,a.lifetime_paid_cents,count(l.id) filter(where l.state in ('pending','available','settled')) as earning_entries,coalesce(sum(l.amount_cents) filter(where l.direction='credit' and l.state in ('pending','available','settled')),0) as credited_cents,coalesce(sum(l.platform_fee_cents) filter(where l.direction='credit' and l.state in ('pending','available','settled')),0) as platform_fees_cents from public.monetization_accounts a left join public.monetization_ledger l on l.account_user_id=a.user_id group by a.user_id,a.currency,a.available_cents,a.pending_cents,a.lifetime_earned_cents,a.lifetime_paid_cents;
commit;
